window.docContents[249].resolve({"/Backmatter/Mathematical-references/#Backmatter___MathematicalReferences___heading-1":{"contents":"[BGP] J. Bernstein, I. Gelfand, V. Ponomarev, Coxeter functors and Gabriel's theorem, Russian Math. Surveys 28 (1973), no. 2, 17–32.\n\n[Cu] C. Curtis, Pioneers of Representation Theory: Frobenius, Burnside, Schur, and Brauer, Amer. Math. Soc., 1999.\n\n[CR] C. Curtis and I. Reiner, Representation Theory of Finite Groups and Associative Algebras, Amer. Math. Soc., 2006.\n\n[FH] W. Fulton and J. Harris, Representation Theory, A First Course, Springer, New York, 1991.\n\n[Fr] P. J. Freyd, Abelian Categories, an Introduction to the Theory of Functors, Harper and Row, 1964.\n\n[Ki] A. A. Kirillov Jr., An Introduction to Lie Groups and Lie Algebras, Cambridge University Press, 2008.\n\n[McL] S. Mac Lane, Categories for a Working Mathematician: 2nd ed., Graduate Texts in Mathematics 5, Springer, 1998.\n\n[S] J.-P. Serre, Linear Representations of Finite Groups, Springer-Verlag, 1997.\n\n[W] C. Weibel, An Introduction to Homological Algebra, Cambridge Univ. Press, 1994.\n\n\n","context":"Introduction to Representation Theory\tBackmatter\tMathematical references","header":"Mathematical references","id":"/Backmatter/Mathematical-references/#Backmatter___MathematicalReferences___heading-1"},"/2___-Basic-notions-of-representation-theory/2___7___-Examples-of-algebras/#chapter-02___section-2-7":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory","header":"2.7. Examples of algebras","id":"/2___-Basic-notions-of-representation-theory/2___7___-Examples-of-algebras/#chapter-02___section-2-7"},"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/5___25___3___-Principal-series/#chapter-05___section-5-25___subsection-5-25-3":{"contents":"\n\n\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.25. Representations of $GL_2(\\mathbb{F}_q)$","header":"5.25.3. Principal series","id":"/5___-Representations-of-finite-groups___-Further-results/5___25___-Representations-of-___GL_2_LPAR____mathbb___F____q_RPAR____/5___25___3___-Principal-series/#chapter-05___section-5-25___subsection-5-25-3"},"/6___-Quiver-representations/6___1___-Problems/Theorem___-Connected-quiver-is-finite-type-iff-Dynkin/#Chapter6___Problem6___1___5_theorem___heading-1":{"contents":"Theorem. A connected quiver Q is of finite type if and only if the corresponding unoriented graph (i.e., with directions of arrows forgotten) is a Dynkin diagram (see Theorem 6.5.2 below).\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.1. Problems\tTheorem: Connected quiver is finite type iff Dynkin","header":"6.1. Problems","id":"/6___-Quiver-representations/6___1___-Problems/Theorem___-Connected-quiver-is-finite-type-iff-Dynkin/#Chapter6___Problem6___1___5_theorem___heading-1"}});
